package com.hsm.account.dto;
import jakarta.validation.constraints.*;
public final class AuthDtos { private AuthDtos(){} public record RegisterRequest(@NotBlank @Email String email,@NotBlank @Size(min=8) @Pattern(regexp=".*[A-Za-z].*",message="must contain a letter") @Pattern(regexp=".*[0-9].*",message="must contain a digit") String password){} public record LoginRequest(@NotBlank @Email String email,@NotBlank String password){} public record VerifyRequest(@NotBlank @Email String email,@NotBlank @Pattern(regexp="\\d{6}") String otp){} public record EmailRequest(@NotBlank @Email String email){} public record UserResponse(Long id,String email,String role,boolean verified){} public record LoginResponse(UserResponse user){} }
